import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        ArrayDeque<Character> stack = new ArrayDeque<>();
        boolean ok = true;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(' || c == '[' || c == '{') {
                stack.push(c);
            } else {
                char want = '{';
                if (c == ')') want = '(';
                else if (c == ']') want = '[';
                if (stack.isEmpty() || stack.pop() != want) {
                    ok = false;
                    break;
                }
            }
        }
        System.out.println(ok && stack.isEmpty());
    }
}

