import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int r = sc.nextInt();
        int c = sc.nextInt();
        int[][] g = new int[r][c];
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) g[i][j] = sc.nextInt();
        }
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};
        int islands = 0;
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                if (g[i][j] != 1) continue;
                islands++;
                ArrayDeque<int[]> stack = new ArrayDeque<>();
                stack.push(new int[]{i, j});
                g[i][j] = 0;
                while (!stack.isEmpty()) {
                    int[] cur = stack.pop();
                    for (int d = 0; d < 4; d++) {
                        int ni = cur[0] + dr[d];
                        int nj = cur[1] + dc[d];
                        if (ni < 0 || ni >= r || nj < 0 || nj >= c) continue;
                        if (g[ni][nj] != 1) continue;
                        g[ni][nj] = 0;
                        stack.push(new int[]{ni, nj});
                    }
                }
            }
        }
        System.out.println(islands);
    }
}

