            adj.get(u).add(v);
            indeg[v]++;
        }
        PriorityQueue<Integer> ready = new PriorityQueue<>();
        for (int i = 0; i < n; i++) {
            if (indeg[i] == 0) ready.add(i);
        }
        StringBuilder sb = new StringBuilder();
        int placed = 0;
        while (!ready.isEmpty()) {
            int u = ready.poll();
            placed++;
            if (sb.length() > 0) sb.append(' ');
            sb.append(u);
            for (int v : adj.get(u)) {
                indeg[v]--;
                if (indeg[v] == 0) ready.add(v);
            }
        }
        System.out.println(placed == n ? sb.toString() : "cycle");
    }
}

