        int r = sc.nextInt();
        int c = sc.nextInt();
        int[][] g = new int[r][c];
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) g[i][j] = sc.nextInt();
        }
        long border = 0;
        long inside = 0;
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                if (i == 0 || i == r - 1 || j == 0 || j == c - 1) border += g[i][j];
                else inside += g[i][j];
            }
        }
        System.out.println(border);
        System.out.println(inside);
    }
}

