  get length(): number {
    return this.#items.length;
  }
  get isFull(): boolean {
    return this.#items.length === this.#capacity;
  }
  *[Symbol.iterator](): Generator<T> {
    yield* this.#items;
  }
}
const buffer = new RingBuffer<string>(capacity);
