exercises.solution:
WITH RECURSIVE months(month) AS (
  SELECT '2023-01'
  UNION ALL
  SELECT strftime('%Y-%m', date(month || '-01', '+1 month')) FROM months WHERE month < '2023-12'
)
SELECT month FROM months ORDER BY month;

