WITH totals AS (
  SELECT order_id, SUM(quantity * unit_price) AS total FROM order_items GROUP BY order_id
)
SELECT c.name AS customer, ROUND(SUM(t.total), 2) AS spend
FROM customers c
JOIN orders o ON o.customer_id = c.id AND o.status = 'shipped'
JOIN totals t ON t.order_id = o.id
GROUP BY c.id, c.name
ORDER BY spend DESC, customer;
